//! This code was AUTOGENERATED using the Codama library.
/// On-chain flags for indexer tranching. Each flag is a full byte so off-chain
/// consumers can filter accounts via `memcmp`. Balance-derived flags are synced
/// automatically on every balance-mutating instruction. Pulse-derived flags are
/// updated in `pulse_health`.
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[derive(Debug, Clone, borsh::BorshSerialize, borsh::BorshDeserialize, PartialEq)]
pub struct IndexerFlags {
    /// 1 if the account has no liabilities
    pub is_lending_only: u8,
    /// 1 if the account has no balances above the dust threshold
    pub is_empty: u8,
    /// 1 if the account has exactly one liability position
    pub is_single_borrower: u8,
    /// 1 if the account has ever entered receivership (liquidation or
    /// deleverage), permanent.
    pub has_ever_been_liquidated: u8,
    /// 1 if the account has ever been forcibly deleveraged (permanent, never
    /// unset)
    pub has_ever_been_deleveraged: u8,
    /// 1 if `handle_bankruptcy` has ever been executed on this account
    /// (permanent, never unset)
    pub has_been_bankrupted: u8,
    /// 1 if the account has any liability on a bank with `RiskTier::Isolated`.
    /// Note: Not authoritative due to a variety of edge cases, such as a
    /// Bank being configured from Collateral -> Isolated after the user
    /// deposits. Set at borrow time and refreshed best-effort by pulse from
    /// live bank state. Cleared by balance-derived sync only when liability
    /// count reaches zero.
    pub has_isolated: u8,
    /// 1 if the account has a STAKED asset tag position
    pub has_staked: u8,
    /// 1 if the account has a KAMINO asset tag position
    pub has_kamino: u8,
    /// 1 if the account has a DRIFT asset tag position
    pub has_drift: u8,
    /// 1 if the account has a JUPLEND asset tag position
    pub has_juplend: u8,
    /// 1 if maintenance health was negative at last pulse
    pub was_liquidatable: u8,
    /// 1 if equity health was negative at last pulse
    pub was_underwater: u8,
    /// 1 if account was active within the last 30 days. Raised to 1 on every
    /// balance-mutating instruction; can only transition 1 → 0 at pulse time,
    /// when the elapsed-since-`last_update` check fails.
    /// Combined with `is_empty`, indicates an account pending closure.
    pub was_active30d: u8,
    /// 1 if account was active within the last 60 days. Raised to 1 on every
    /// balance-mutating instruction; can only transition 1 → 0 at pulse time,
    /// when the elapsed-since-`last_update` check fails.
    /// Combined with `is_empty`, indicates an account eligible for
    /// permissionless close.
    pub was_active60d: u8,
    /// 1 if net equity value was greater than $0 and less than $1 at last pulse
    pub has_trivial_balance: u8,
    pub pad: [u8; 8],
}
